SET local check_function_bodies = off;

CREATE SCHEMA "private";

CREATE TABLE "public"."activity_log" (
  "activity_log_id" bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "reference_code"  text                     NOT NULL,
  "old_status_id"   bigint                   NOT NULL DEFAULT '1'::bigint,
  "new_status_id"   bigint                   NOT NULL DEFAULT '1'::bigint,
  "timestamp"       timestamp with time zone NOT NULL DEFAULT now(),
  "member_notes"    text,
  "internal_notes"  text,
  "member_message"  text,
  "changed_by"      uuid,
  CONSTRAINT "activity_log_internal_notes_length" CHECK ((char_length(internal_notes) <= 250)),
  CONSTRAINT "activity_log_member_notes_length" CHECK ((char_length(member_notes) <= 250)),
  CONSTRAINT "activity_log_pkey" PRIMARY KEY (activity_log_id)
);

ALTER TABLE "public"."activity_log"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."care_requests" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "first"             text,
  "last"              text,
  "anonymous_flag"    boolean                  NOT NULL DEFAULT false,
  "request_type_id"   integer                  NOT NULL,
  "status_type_id"    bigint                   NOT NULL,
  "contact_method_id" bigint                   NOT NULL,
  "urgency_type_id"   bigint                   NOT NULL,
  "no_contact_flag"   boolean                  NOT NULL DEFAULT false,
  "archived_flag"     boolean                  NOT NULL DEFAULT false,
  "member_notes"      text,
  "internal_notes"    text,
  "phone"             text,
  "email"             text,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "care_requests_email_format" CHECK (((char_length(email) <= 254) AND (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text))),
  CONSTRAINT "care_requests_first_length" CHECK ((char_length(first) <= 100)),
  CONSTRAINT "care_requests_internal_notes_length" CHECK ((char_length(internal_notes) <= 250)),
  CONSTRAINT "care_requests_last_length" CHECK ((char_length(last) <= 100)),
  CONSTRAINT "care_requests_member_notes_length" CHECK ((char_length(member_notes) <= 250)),
  CONSTRAINT "care_requests_phone_format" CHECK ((phone ~ '^\+?[0-9 ().-]{7,20}$'::text)),
  CONSTRAINT "care_requests_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."care_requests"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."contact_method_types" (
  "contact_method_type_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "contact_method"         text   NOT NULL,
  CONSTRAINT "contact_method_types_pkey" PRIMARY KEY (contact_method_type_id)
);

ALTER TABLE "public"."contact_method_types"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."request_type" (
  "request_type_id" integer GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."care_types_id_seq") NOT NULL,
  "request_type"    text    NOT NULL DEFAULT ''::text,
  CONSTRAINT "care_types_pkey" PRIMARY KEY (request_type_id)
);

ALTER TABLE "public"."request_type"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."staff" (
  "user_id"    uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "staff_pkey" PRIMARY KEY (user_id)
);

ALTER TABLE "public"."staff"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."staff" FROM "anon";

CREATE TABLE "public"."status_types" (
  "status_type_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "status_type"    text   NOT NULL,
  CONSTRAINT "status_types_pkey" PRIMARY KEY (status_type_id)
);

ALTER TABLE "public"."status_types"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."urgency_type" (
  "urgency_type_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "urgency"         text   NOT NULL,
  CONSTRAINT "urgency_type_pkey" PRIMARY KEY (urgency_type_id)
);

ALTER TABLE "public"."urgency_type"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION private.activity_log_after_insert()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update public.care_requests
  set status_type_id = new.new_status_id
  where reference_code = new.reference_code
    and status_type_id is distinct from new.new_status_id;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.activity_log_before_insert()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  new.changed_by := (select auth.uid());
  -- a direct insert gets its old status from the request; inserts from the request trigger already carry it
  if pg_trigger_depth() = 1 then
    select status_type_id into new.old_status_id
    from public.care_requests
    where reference_code = new.reference_code;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.care_requests_log_status_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- depth 1 = a staff edit; deeper means the change came from an activity_log insert, which is already logged
  if pg_trigger_depth() = 1 and new.status_type_id is distinct from old.status_type_id then
    insert into public.activity_log (reference_code, old_status_id, new_status_id)
    values (new.reference_code, old.status_type_id, new.status_type_id);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.care_requests_sync_fields()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
  else
    new.created_at := old.created_at;
    new.updated_at := now();
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_reference_code()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'INSERT' then
    new.reference_code := private.generate_reference_code();
  else
    new.reference_code := old.reference_code;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.generate_reference_code()
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';  -- 31 chars
  code text;
  b int;
begin
  loop
    code := '';
    while length(code) < 8 loop
      b := get_byte(extensions.gen_random_bytes(1), 0);
      -- reject 248..255 so every character is equally likely
      if b < 248 then
        code := code || substr(alphabet, (b % 31) + 1, 1);
      end if;
    end loop;
    code := 'ZC-' || substr(code, 1, 4) || '-' || substr(code, 5, 4);
    exit when not exists (select 1 from public.care_requests where reference_code = code);
  end loop;
  return code;
end;
$function$;

CREATE OR REPLACE FUNCTION private.is_staff()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (select 1 from public.staff where user_id = (select auth.uid()));
$function$;

CREATE OR REPLACE FUNCTION public.get_care_request (
  p_reference_code text
)
  RETURNS TABLE (
    reference_code    text,
    first             text,
    last              text,
    phone             text,
    email             text,
    anonymous_flag    boolean,
    no_contact_flag   boolean,
    archived_flag     boolean,
    request_type_id   integer,
    request_type      text,
    urgency_type_id   bigint,
    urgency           text,
    contact_method_id bigint,
    contact_method    text,
    status_type_id    bigint,
    status_type       text,
    member_notes      text,
    created_at        timestamp with time zone,
    updated_at        timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select r.reference_code, r.first, r.last, r.phone, r.email,
         r.anonymous_flag, r.no_contact_flag, r.archived_flag,
         r.request_type_id, rt.request_type,
         r.urgency_type_id, u.urgency,
         r.contact_method_id, cm.contact_method,
         r.status_type_id, s.status_type,
         r.member_notes, r.created_at, r.updated_at
  from public.care_requests r
  join public.request_type rt on rt.request_type_id = r.request_type_id
  join public.urgency_type u on u.urgency_type_id = r.urgency_type_id
  join public.contact_method_types cm on cm.contact_method_type_id = r.contact_method_id
  join public.status_types s on s.status_type_id = r.status_type_id
  where r.reference_code = upper(trim(p_reference_code));  -- tolerate "zc-7k3m-9qxp " as typed
$function$;

CREATE OR REPLACE FUNCTION public.get_request_updates (
  p_reference_code text
)
  RETURNS TABLE (
    activity_log_id bigint,
    reference_code  text,
    old_status_id   bigint,
    old_status      text,
    new_status_id   bigint,
    new_status      text,
    member_notes    text,
    member_message  text,
    "timestamp"     timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select a.activity_log_id, a.reference_code,
         a.old_status_id, os.status_type,
         a.new_status_id, ns.status_type,
         a.member_notes, a.member_message, a."timestamp"
  from public.activity_log a
  join public.status_types os on os.status_type_id = a.old_status_id
  join public.status_types ns on ns.status_type_id = a.new_status_id
  where a.reference_code = upper(trim(p_reference_code))
  order by a."timestamp";
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.submit_care_request (
  p_request_type_id   integer,
  p_urgency_type_id   bigint,
  p_contact_method_id bigint,
  p_first             text    DEFAULT NULL::text,
  p_last              text    DEFAULT NULL::text,
  p_phone             text    DEFAULT NULL::text,
  p_email             text    DEFAULT NULL::text,
  p_anonymous         boolean DEFAULT false,
  p_no_contact        boolean DEFAULT false,
  p_member_notes      text    DEFAULT NULL::text
)
  RETURNS text
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.care_requests (
    request_type_id, urgency_type_id, contact_method_id, first, last, phone, email,
    anonymous_flag, no_contact_flag, member_notes,
    status_type_id, internal_notes
  ) values (
    p_request_type_id, p_urgency_type_id, p_contact_method_id,
    nullif(trim(p_first), ''), nullif(trim(p_last), ''),
    nullif(trim(p_phone), ''), lower(nullif(trim(p_email), '')),
    p_anonymous, p_no_contact, p_member_notes,
    1, null  -- always starts as "Received", no internal notes
  )
  returning reference_code;
$function$;

