ALTER TABLE "public"."care_requests"
  ADD CONSTRAINT "care_requests_contact_method_id_fkey" FOREIGN KEY (contact_method_id) REFERENCES public.contact_method_types(contact_method_type_id) ON UPDATE CASCADE
    ON DELETE RESTRICT;

ALTER TABLE "public"."care_requests"
  ADD CONSTRAINT "care_requests_request_type_id_fkey" FOREIGN KEY (request_type_id) REFERENCES public.request_type(request_type_id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE "public"."staff"
  ADD CONSTRAINT "staff_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."activity_log"
  ADD CONSTRAINT "activity_log_new_status_id_fkey" FOREIGN KEY (new_status_id) REFERENCES public.status_types(status_type_id) ON UPDATE CASCADE ON DELETE SET DEFAULT;

ALTER TABLE "public"."activity_log"
  ADD CONSTRAINT "activity_log_old_status_id_fkey" FOREIGN KEY (old_status_id) REFERENCES public.status_types(status_type_id) ON UPDATE CASCADE ON DELETE SET DEFAULT;

ALTER TABLE "public"."care_requests"
  ADD CONSTRAINT "care_requests_status_type_id_fkey" FOREIGN KEY (status_type_id) REFERENCES public.status_types(status_type_id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE "public"."care_requests"
  ADD CONSTRAINT "care_requests_urgency_type_id_fkey" FOREIGN KEY (urgency_type_id) REFERENCES public.urgency_type(urgency_type_id) ON UPDATE CASCADE ON DELETE RESTRICT;

CREATE INDEX activity_log_changed_by_idx ON public.activity_log USING btree (changed_by);

CREATE INDEX activity_log_new_status_id_idx ON public.activity_log USING btree (new_status_id);

CREATE INDEX activity_log_old_status_id_idx ON public.activity_log USING btree (old_status_id);

CREATE INDEX activity_log_reference_code_idx ON public.activity_log USING btree (reference_code);

CREATE INDEX care_requests_contact_method_id_idx ON public.care_requests USING btree (contact_method_id);

CREATE INDEX care_requests_created_at_idx ON public.care_requests USING btree (created_at DESC);

CREATE INDEX care_requests_request_type_id_idx ON public.care_requests USING btree (request_type_id);

CREATE INDEX care_requests_status_type_id_idx ON public.care_requests USING btree (status_type_id);

CREATE INDEX care_requests_urgency_type_id_idx ON public.care_requests USING btree (urgency_type_id);

CREATE TRIGGER activity_log_after_insert
  AFTER INSERT ON public.activity_log
  FOR EACH ROW
  EXECUTE FUNCTION private.activity_log_after_insert();

CREATE TRIGGER activity_log_before_insert
  BEFORE INSERT ON public.activity_log
  FOR EACH ROW
  EXECUTE FUNCTION private.activity_log_before_insert();

CREATE TRIGGER care_requests_enforce_reference_code
  BEFORE INSERT OR UPDATE ON public.care_requests
  FOR EACH ROW
  EXECUTE FUNCTION private.enforce_reference_code();

CREATE TRIGGER care_requests_log_status_change
  AFTER UPDATE OF status_type_id ON public.care_requests
  FOR EACH ROW
  EXECUTE FUNCTION private.care_requests_log_status_change();

CREATE TRIGGER care_requests_sync_fields
  BEFORE INSERT OR UPDATE ON public.care_requests
  FOR EACH ROW
  EXECUTE FUNCTION private.care_requests_sync_fields();

CREATE POLICY "Staff can add activity log entries" ON "public"."activity_log"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (( SELECT private.is_staff() AS is_staff));

CREATE POLICY "Staff can view activity log" ON "public"."activity_log"
  FOR SELECT
  TO "authenticated"
  USING (( SELECT private.is_staff() AS is_staff));

CREATE POLICY "Staff can create care requests" ON "public"."care_requests"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (( SELECT private.is_staff() AS is_staff));

CREATE POLICY "Staff can update care requests" ON "public"."care_requests"
  FOR UPDATE
  TO "authenticated"
  USING (( SELECT private.is_staff() AS is_staff))
  WITH CHECK (( SELECT private.is_staff() AS is_staff));

CREATE POLICY "Staff can view care requests" ON "public"."care_requests"
  FOR SELECT
  TO "authenticated"
  USING (( SELECT private.is_staff() AS is_staff));

CREATE POLICY "Anyone can read contact method types" ON "public"."contact_method_types"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Anyone can read request types" ON "public"."request_type"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Staff can see their own staff row" ON "public"."staff"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "Anyone can read status types" ON "public"."status_types"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Anyone can read urgency types" ON "public"."urgency_type"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

ALTER PUBLICATION "supabase_realtime" ADD TABLE "public"."care_requests";

COMMENT ON TABLE "public"."request_type" IS 'care types used for care requests';

